{
  "story": "How does RLHF turn human feedback into model behavior? Start with two answers from an instruction-tuned Answer model. Follow Human ranking into Reward model training. Advance to Reward-guided update to see how learned reward changes the Answer model. Use Previous and Next to inspect each state.",
  "aha": {
    "stateId": "reward-guided-update",
    "observation": "Human rankings train a reward model; reinforcement learning uses its scores to make higher-reward answers more likely."
  },
  "layout": {
    "preset": "approved-card",
    "width": 640
  },
  "parts": [
    {
      "id": "training-rail",
      "kind": "step-rail",
      "presentation": "Place below the explanation and instructions. Show the active state and completed trace here, not inside the picture.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "training-picture",
      "kind": "fixed-picture",
      "presentation": "Use the canonical pipeline arrangement with fixed named regions and wrapped labels. Change one region's highlight at a time. Keep every region stationary.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-explanation",
      "kind": "active-callout",
      "presentation": "Anchor to the highlighted region. Explain its role without duplicating readout values.",
      "bind": {
        "target": "state.calloutRegion",
        "text": "state.sentence",
        "reason": "state.why"
      }
    },
    {
      "id": "training-evidence",
      "kind": "value-readout",
      "presentation": "Place below the picture. Reserve the last row for bound status. These categorical readouts use no units, numerical scales, or rounding.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "training-state",
      "kind": "index",
      "items": "variant.states",
      "label": "Training state",
      "presentation": "Provide Previous and Next with accessible names, visible focus, and keyboard operation. Preserve names when disabled at boundaries. Default to the first state. Bounds are the first and last states; each action advances one state. Every state persists until another action. Capture Reward-guided update as the reference state."
    },
    {
      "id": "reset",
      "kind": "reset",
      "label": "Reset",
      "presentation": "Restore the first state and all defaults. Support keyboard activation and visible focus. Brief parameter-control budget: zero. Navigation and Reset are separate from that budget."
    }
  ],
  "data": {
    "variants": [
      {
        "label": "Brief RLHF: one illustrative preference",
        "regions": [
          {
            "id": "answer-model",
            "label": "Answer model",
            "values": [
              "Prompt: Explain rain to a child.",
              "Answer A: Water falls from clouds.",
              "Answer B: Hydrometeors precipitate."
            ]
          },
          {
            "id": "human-ranking",
            "label": "Human ranking",
            "actors": [
              "Human reviewer"
            ]
          },
          {
            "id": "reward-model",
            "label": "Reward model",
            "actors": [
              "Learned preference scorer"
            ]
          }
        ],
        "links": [
          {
            "from": "answer-model",
            "to": "human-ranking",
            "label": "Answers for comparison"
          },
          {
            "from": "human-ranking",
            "to": "reward-model",
            "label": "Ranking used for training"
          },
          {
            "from": "reward-model",
            "to": "answer-model",
            "label": "Reward used for reinforcement learning"
          }
        ],
        "states": [
          {
            "id": "generate-answers",
            "label": "Generate answers",
            "short": "Generate",
            "sentence": "The instruction-tuned Answer model generates two candidate answers to the same prompt.",
            "why": "The prompt and candidate answers stay fixed throughout this simplified example.",
            "active": [
              "answer-model"
            ],
            "calloutRegion": "answer-model",
            "readouts": [
              {
                "id": "status",
                "label": "Status",
                "value": "Candidates available; human feedback not collected."
              }
            ]
          },
          {
            "id": "collect-ranking",
            "label": "Collect human ranking",
            "short": "Rank",
            "sentence": "The human reviewer compares the candidates for clarity to a child.",
            "why": "This fixed, illustrative preference supplies training feedback; the Answer model has not changed.",
            "active": [
              "human-ranking"
            ],
            "calloutRegion": "human-ranking",
            "readouts": [
              {
                "id": "human-preference",
                "label": "Human preference",
                "value": "Answer A preferred over Answer B."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Human ranking collected; Answer model unchanged."
              }
            ]
          },
          {
            "id": "train-reward-model",
            "label": "Train reward model",
            "short": "Learn reward",
            "sentence": "The Reward model learns to predict human rankings, providing a scoring signal for reinforcement learning.",
            "why": "Real training uses many comparisons; this illustration assumes the Reward model reproduces the example preference.",
            "active": [
              "reward-model"
            ],
            "calloutRegion": "reward-model",
            "readouts": [
              {
                "id": "predicted-reward",
                "label": "Predicted reward order",
                "value": "Answer A above Answer B."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Reward model trained; Answer model unchanged."
              }
            ]
          },
          {
            "id": "reward-guided-update",
            "label": "Reward-guided update",
            "short": "Update",
            "sentence": "Reinforcement learning updates the Answer model using Reward model scores rather than another human vote.",
            "why": "The illustrated update increases the likelihood of the higher-reward answer; learned reward remains an imperfect proxy for human preferences.",
            "active": [
              "answer-model"
            ],
            "calloutRegion": "answer-model",
            "readouts": [
              {
                "id": "update-signal",
                "label": "Update signal",
                "value": "Reward model scores, learned from Human ranking."
              },
              {
                "id": "model-change",
                "label": "Compared with before the update",
                "value": "Answer A is now more likely."
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Reward-guided update complete; held for inspection."
              }
            ]
          }
        ]
      }
    ]
  }
}
